        // But we must ensure that the call is made by the owner. As noted, msg.sender is the test contract, which is the owner. So the require(msg.sender == owner) passes.
        // So we can proceed.

        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call reverts exactly when the requested amount exceeds c's balance.
        assert(reverted == (amount > balBefore));
    }

